CREATE OR REPLACE FUNCTION public.subscription_posts_used(_user uuid,_start timestamptz) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM (SELECT post_id FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=_start UNION SELECT id FROM public.posts WHERE user_id=_user AND created_at>=_start UNION SELECT id FROM public.free_work_entries WHERE user_id=_user AND created_at>=_start) recorded $$;
REVOKE ALL ON FUNCTION public.subscription_posts_used(uuid,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.subscription_posts_used(uuid,timestamptz) TO service_role;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.consume_post_slot(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'SELECT count(*) INTO used FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=start_time','SELECT public.subscription_posts_used(_user,start_time) INTO used'); def:=replace(def,'IF used>=cap THEN','IF EXISTS(SELECT 1 FROM public.posts WHERE id=_id AND user_id=_user) OR EXISTS(SELECT 1 FROM public.free_work_entries WHERE id=_id AND user_id=_user) THEN used:=greatest(used-1,0); END IF; IF used>=cap THEN'); EXECUTE def; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.my_post_quota99()'::regprocedure) INTO def; def:=replace(def,'(SELECT count(*) FROM public.monthly_post_usage WHERE user_id=auth.uid() AND used_at>=CASE WHEN public.has_paid_bell(auth.uid()) THEN date_trunc(''month'',now() AT TIME ZONE ''Asia/Kolkata'') AT TIME ZONE ''Asia/Kolkata'' ELSE ''-infinity''::timestamptz END)','public.subscription_posts_used(auth.uid(),CASE WHEN public.has_paid_bell(auth.uid()) THEN date_trunc(''month'',now() AT TIME ZONE ''Asia/Kolkata'') AT TIME ZONE ''Asia/Kolkata'' ELSE ''-infinity''::timestamptz END)'); EXECUTE def; END $$;